practice.solutionCode:
public class Main {
    public static void main(String[] args) {
        int angleQuarter = 2;
        String quadrant = switch (angleQuarter) {
            case 1 -> "Quadrant I: (+, +)";
            case 2 -> "Quadrant II: (-, +)";
            case 3 -> "Quadrant III: (-, -)";
            case 4 -> "Quadrant IV: (+, -)";
            default -> "Invalid Quadrant";
        };
        System.out.println("Result: " + quadrant);
    }
}

