public class Main {
    public static void main(String[] args) {
        String vehicleType = "SUV";
        int mpgRating = switch (vehicleType) {
            case "SEDAN" -> 35;
            case "HYBRID" -> 52;
            case "TRUCK" -> 18;
            case "SUV" -> {
                int base = 22;
                int penalty = 2;
                yield base - penalty;
            }
            default -> 0;
        };
        System.out.println("Estimated MPG: " + mpgRating);
    }
}

