public class Main {
    public static void main(String[] args) {
        String incomeTier = "HIGH";
        double surchargeRate = switch (incomeTier) {
            case "LOW" -> 0.0;
            case "MEDIUM" -> 0.05;
            case "HIGH" -> {
                double base = 0.10;
                double educationCess = 0.02;
                yield base + educationCess;
            }
            default -> 0.0;
        };
        System.out.println("Tax Surcharge: " + (surchargeRate * 100) + "%");
    }
}

