public class Main {
    public static void main(String[] args) {
        int weightKg = 15;
        int category = weightKg > 20 ? 3 : (weightKg > 5 ? 2 : 1);
        String shipping = switch (category) {
            case 1 -> "Light Package ($5 shipping)";
            case 2 -> "Standard Package ($15 shipping)";
            case 3 -> "Heavy Cargo ($50 shipping)";
            default -> "Unknown";
        };
        System.out.println("Shipping: " + shipping);
    }
}
